    deepExplanation: "Step 1 — Keep only k largest values.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction kthLargest(nums: readonly number[], k: number): number | undefined {\n  if (k < 1 || k > nums.length) return undefined;\n\n  const heap: number[] = [];\n\n  const bubbleUp = (index: number): void => {\n    while (index > 0) {\n      const parent = Math.floor((index - 1) / 2);\n      if (heap[parent]! <= heap[index]!) break;\n\n      [heap[parent], heap[index]] = [heap[index]!, heap[parent]!];\n      index = parent;\n    }\n  };\n\n  const bubbleDown = (index: number): void => {\n    while (true) {\n      const left = index * 2 + 1;\n      const right = left + 1;\n      let smallest = index;\n\n      if (left < heap.length && heap[left]! < heap[smallest]!) smallest = left;\n      if (right < heap.length && heap[right]! < heap[smallest]!) smallest = right;\n      if (smallest === index) break;\n\n      [heap[index], heap[smallest]] = [heap[smallest]!, heap[index]!];\n      index = smallest;\n    }\n  };\n\n  for (const value of nums) {\n    heap.push(value);\n    bubbleUp(heap.length - 1);\n\n    if (heap.length > k) {\n      heap[0] = heap.pop()!;\n      bubbleDown(0);\n    }\n  }\n\n  return heap[0];\n}\n```\n\nStep 2 — WITH BUILT-IN:\n```ts\nfunction kthLargestUsingBuiltIns(\n  nums: readonly number[],\n  k: number,\n): number | undefined {\n  if (k < 1 || k > nums.length) return undefined;\n\n  return [...nums].sort((a, b) => b - a)[k - 1];\n}\n```\n\nStep 3 — Example:\n[3,2,1,5,6,4], k=2\ntop 2 values are [5,6]\nanswer = 5.\n\nStep 4 — Complexity:\nHeap: O(n log k) time, O(k) extra space.\nSort: O(n log n) time, O(n) copied input.",
