    expectedAnswer: "To merge k sorted lists efficiently, keep the smallest current head from each list in a min-heap. Remove the smallest node, append it to the result, and insert that node's next item.",
    deepExplanation: "Step 1 — Use heap entries `(value, listIndex, itemIndex)`.\n\nWITHOUT BUILT-IN / CORE:\n```ts\ninterface HeapEntry {\n  value: number;\n  listIndex: number;\n  itemIndex: number;\n}\n\nfunction mergeKSortedLists(\n  lists: readonly (readonly number[])[],\n): number[] {\n  const heap: HeapEntry[] = [];\n\n  const push = (entry: HeapEntry): void => {\n    heap.push(entry);\n    let index = heap.length - 1;\n\n    while (index > 0) {\n      const parent = Math.floor((index - 1) / 2);\n      if (heap[parent]!.value <= heap[index]!.value) break;\n\n      [heap[parent], heap[index]] = [heap[index]!, heap[parent]!];\n      index = parent;\n    }\n  };\n\n  const pop = (): HeapEntry | undefined => {\n    if (heap.length === 0) return undefined;\n    if (heap.length === 1) return heap.pop();\n\n    const result = heap[0];\n    heap[0] = heap.pop()!;\n\n    let index = 0;\n\n    while (true) {\n      const left = index * 2 + 1;\n      const right = left + 1;\n      let smallest = index;\n\n      if (left < heap.length && heap[left]!.value < heap[smallest]!.value) {\n        smallest = left;\n      }\n\n      if (right < heap.length && heap[right]!.value < heap[smallest]!.value) {\n        smallest = right;\n      }\n\n      if (smallest === index) break;\n\n      [heap[index], heap[smallest]] = [heap[smallest]!, heap[index]!];\n      index = smallest;\n    }\n\n    return result;\n  };\n\n  for (let listIndex = 0; listIndex < lists.length; listIndex++) {\n    if (lists[listIndex]!.length > 0) {\n      push({ value: lists[listIndex]![0]!, listIndex, itemIndex: 0 });\n    }\n  }\n\n  const result: number[] = [];\n\n  while (heap.length > 0) {\n    const current = pop()!;\n    result.push(current.value);\n\n    const nextIndex = current.itemIndex + 1;\n    const list = lists[current.listIndex]!;\n\n    if (nextIndex < list.length) {\n      push({\n        value: list[nextIndex]!,\n        listIndex: current.listIndex,\n        itemIndex: nextIndex,\n      });\n    }\n  }\n\n  return result;\n}\n```\n\nStep 2 — WITH BUILT-IN baseline:\n```ts\nfunction mergeKUsingBuiltIns(\n  lists: readonly (readonly number[])[],\n): number[] {\n  return lists\n    .flatMap((list) => [...list])\n    .sort((a, b) => a - b);\n}\n```\n\nStep 3 — Example:\n[1,4], [2,5], [3,6]\n→ [1,2,3,4,5,6].\n\nStep 4 — Complexity:\nHeap method: O(N log k), where N is total elements.\nSpace: O(k) heap plus output.",
